import khPlate from '@admin/assets/brand/kh-plate.png';
import { cn } from '@admin/shared/lib/cn';

/**
 * The full Kulatissa Hardware plate (bolts and the Sinhala label), the app icon's large drawing without
 * its tile; the same artwork and component as the till's sign-in screen. Generated by build/appicon.swift;
 * don't edit the PNG by hand. It carries the shop's name in Sinhala, so it has alt text, unlike BrandMark.
 */
export function BrandPlate({ className }: { className?: string }) {
    return (
        <img
            src={khPlate}
            alt="Kulatissa Hardware (කුලතිස්ස)"
            draggable={false}
            className={cn('select-none', className)}
        />
    );
}
